import { GoalConfidenceService } from "./GoalConfidenceService";
import { getLocalDateKey } from "../utils/localDate";
import { createBodyCompositionEstimate, formatBodyCompositionRange } from "./BodyCompositionEstimateService";
import { selectValidDexaScans } from "./DEXAReadModelAdapter";

const BODY_FAT_GOAL_ID = "goal_maintain_8_9_body_fat";
const LEAN_MASS_GOAL_ID = "goal_preserve_lean_mass";
const VISIBLE_ABS_GOAL_ID = "goal_visible_abs_at_rest";
const DAY_MS = 24 * 60 * 60 * 1000;
const PROJECTION_BUCKET_DAYS = 7;
const PROJECTION_WINDOW_RADIUS_DAYS = 3;
const ROLLING_TREND_WINDOW_DAYS = 7;
const LEAN_MASS_PRESERVATION_RATIO = 0.95;

export function createGoalEvaluationService() {
  return {
    getGoalEvaluations({
      goals = [],
      dexaScans = [],
      weightEntries = [],
      progressPhotos = [],
      protocols = [],
      nutritionContext = null,
      photoAnalyses = [],
      trainingPerformance = null,
      now = new Date(),
    } = {}) {
      const evidence = {
        dexaScans: selectValidDexaScans(dexaScans),
        invalidDexaCount: dexaScans.length - selectValidDexaScans(dexaScans).length,
        weightEntries: sortByDate(weightEntries, "measuredAt"),
        progressPhotos: sortByDate(progressPhotos, "date"),
        protocols,
        nutritionContext,
        photoAnalyses,
        trainingPerformance,
        now,
      };

      return goals.map((goal) => evaluateGoal(goal, evidence));
    },
  };
}

export const GoalEvaluationService = createGoalEvaluationService();

function evaluateGoal(goal, evidence) {
  if (goal.id === VISIBLE_ABS_GOAL_ID || goal.metricKey === "visualDefinition") {
    return evaluateVisibleAbs(goal, evidence);
  }

  if (goal.id === BODY_FAT_GOAL_ID || goal.metricKey === "bodyFatPercentage") {
    return evaluateBodyFat(goal, evidence);
  }

  if (goal.id === LEAN_MASS_GOAL_ID || goal.metricKey === "leanMass") {
    return evaluateLeanMass(goal, evidence);
  }

  return createEvaluation({
    goal,
    current: "Pending",
    target: formatGoalTarget(goal),
    summary: "Add supporting evidence to evaluate this goal.",
    progress: 0,
    confidence: 0,
    missingEvidence: ["supporting_evidence"],
  });
}

function evaluateVisibleAbs(goal, evidence) {
  const latestDEXA = evidence.dexaScans.at(-1) ?? null;
  const explicitlyCompleted = goal?.status === "completed" && goal?.completion?.userConfirmed === true;

  if (!latestDEXA) {
    return createEvaluation({
      goal,
      title: "Visible Abs",
      current: "Pending",
      target: "Visible",
      summary: missingDexaSummary(evidence, "calibrate progress toward visible abs"),
      progress: 0,
      confidence: 0,
      missingEvidence: ["dexa_scan", "progress_photos"],
    });
  }

  const bodyCompositionEstimate = getBodyCompositionEstimate(latestDEXA, evidence);
  const numericalThresholdReached = latestDEXA.bodyFatPercentage <= (goal.supportingBodyFatRange?.max ?? 9);
  const currentBodyFatEstimate = bodyCompositionEstimate?.pointEstimateBodyFatPercent ?? null;
  const bodyFatTrend = getBodyFatTrend(evidence.dexaScans);
  const postDexaLoss = getWeightLossAfterDate(
    evidence.weightEntries,
    latestDEXA.measuredAt
  );
  const photosAreConsistent = hasConsistentProgressPhotos(evidence.progressPhotos);
  const leanMassPreservation = getLeanMassPreservationScore(latestDEXA);
  const protocolContextExists = evidence.protocols.some((protocol) =>
    protocol.relatedGoalIds?.includes(goal.id)
  );
  const findings = [
    createFinding({
      id: "dexa_supports_progress",
      status: bodyFatTrend > 0 ? "positive" : "neutral",
      text:
        bodyFatTrend > 0
          ? "DEXA trend supports continued body-composition progress."
          : "DEXA provides calibration, but more trend movement is needed.",
      evidenceTypes: ["dexa"],
    }),
    createFinding({
      id: "weight_trend_supports_fat_loss",
      status: postDexaLoss > 0 ? "positive" : "neutral",
      text:
        postDexaLoss > 0
          ? "Weight trend supports continued fat loss."
          : "Weight trend has not yet confirmed additional post-DEXA loss.",
      evidenceTypes: ["weight"],
    }),
    createFinding({
      id: "progress_photos_consistent",
      status: photosAreConsistent ? "positive" : "neutral",
      text: photosAreConsistent
        ? "Progress photos are captured under consistent conditions."
        : "Progress photos need more consistent conditions.",
      evidenceTypes: ["progress_photo"],
    }),
    createFinding({
      id: "lean_mass_preserved",
      status: leanMassPreservation >= 95 ? "positive" : "risk",
      text:
        leanMassPreservation >= 95
          ? "Lean mass has largely been preserved."
          : "Lean-mass preservation needs confirmation at the next DEXA.",
      evidenceTypes: ["dexa"],
    }),
    createFinding({
      id: "visual_confirmation_pending",
      status: "neutral",
      text: "Visual confirmation of abs at rest has not yet been established.",
      evidenceTypes: ["progress_photo"],
    }),
    createFinding({
      id: "current_body_fat_estimated",
      status: "neutral",
      text: "Current body-fat remains estimated until the next DEXA.",
      evidenceTypes: ["dexa", "weight"],
    }),
  ];
  const confidenceFactors = [
    createConfidenceFactor("dexa_history", "13 DEXA scans support calibration.", 18),
    createConfidenceFactor("weight_history", "Consistent morning weights support trend direction.", 14),
    createConfidenceFactor("photo_history", "Progress photos support visual calibration.", 10),
    createConfidenceFactor("protocol_context", "Protocol schedules provide current context.", 6),
    createConfidenceFactor("nutrition_context", "Nutrition and calorie-burn context are estimated.", -5),
    createConfidenceFactor("visual_scoring", "Visual scoring remains qualitative.", -4),
  ];
  const positiveFindings = findings.filter((finding) => finding.status === "positive")
    .length;
  const progress = clamp(
    48 +
      positiveFindings * 8 +
      clamp(Math.round(bodyFatTrend * 4), 0, 10) +
      clamp(Math.round(postDexaLoss * 2), 0, 8) +
      (protocolContextExists ? 4 : 0),
    0,
    92
  );

  const goalConfidence = getGoalConfidence({
    confidenceFactors,
    evidence,
    findings,
    missingEvidence:
      explicitlyCompleted
        ? []
        : currentBodyFatEstimate === null
        ? ["current_body_fat_calibration"]
        : ["visual_confirmation_at_rest"],
  });
  const projection = attachProjectionConfidence(
    getProjection({
      goal,
      dexaScans: evidence.dexaScans,
      latestDEXA,
      weightEntries: evidence.weightEntries,
      bodyCompositionEstimate,
      progressPhotos: evidence.progressPhotos,
      now: evidence.now,
    }),
    goalConfidence
  );

  return createEvaluation({
    goal,
    title: "Visible Abs",
    current: "Lower abs",
    target: "Visible at rest",
    summary: explicitlyCompleted
      ? "Visible Abs at Rest is complete. You finished the cut at 7.7% body fat while preserving lean mass."
      : numericalThresholdReached
      ? "DEXA threshold reached. A relaxed photo set is the final visual check."
      : "Keep executing the plan.",
    progress: numericalThresholdReached ? null : progress,
    confidence: goalConfidence,
    findings,
    recommendations: [
      createRecommendation(
        "continue_morning_check_ins",
        "Keep logging morning weight under default conditions."
      ),
      createRecommendation(
        "next_photo_cadence",
        "Capture weekly progress photos under the same conditions."
      ),
    ],
    confidenceFactors,
    missingEvidence:
      currentBodyFatEstimate === null
        ? ["current_body_fat_calibration"]
        : ["visual_confirmation_at_rest"],
    projection: numericalThresholdReached ? null : projection,
    lifecycleState: explicitlyCompleted ? "achieved" : numericalThresholdReached ? "awaiting_confirmation" : "active",
    thresholdStatus: numericalThresholdReached ? "complete" : "in_progress",
    confirmationType: numericalThresholdReached ? "relaxed_progress_photos" : null,
    confirmationStatus: explicitlyCompleted ? "confirmed" : numericalThresholdReached ? "pending" : null,
    terminalReason: explicitlyCompleted ? "User confirmed the final qualified Photo Event." : numericalThresholdReached ? "DEXA body-composition threshold reached." : null,
    requiredAction: explicitlyCompleted ? "Choose the next goal." : numericalThresholdReached ? "Review a qualified relaxed progress-photo set." : null,
    actionLabel: explicitlyCompleted ? "View completion" : numericalThresholdReached ? "Review Visible Abs goal" : null,
    actionHref: explicitlyCompleted && goal.completion?.evidence?.finalPhotoSessionId ? `/briefings/photo/${goal.completion.evidence.finalPhotoSessionId}` : numericalThresholdReached ? "/goals/visible-abs" : null,
    transitionReady: explicitlyCompleted,
    metadata: {
      currentBodyFatEstimate,
      currentBodyFatEstimateRange:
        formatBodyCompositionRange(bodyCompositionEstimate),
      bodyCompositionEstimate,
      postDexaLoss,
      bodyFatTrend,
      projectionUnavailableReason: projection && !numericalThresholdReached
        ? null
        : numericalThresholdReached
          ? "The numerical body-composition threshold is reached; completion now depends on visual confirmation at rest."
          : "Validated evidence does not currently support a finish-date estimate.",
    },
  });
}

function evaluateBodyFat(goal, evidence) {
  const latestDEXA = evidence.dexaScans.at(-1) ?? null;

  if (!latestDEXA?.bodyFatPercentage) {
    return createEvaluation({
      goal,
      title: "Maintenance",
      current: "Pending",
      target: formatGoalTarget(goal),
      summary: missingDexaSummary(evidence, "calibrate body-fat progress"),
      progress: 0,
      confidence: 0,
      missingEvidence: ["dexa_scan"],
    });
  }

  const targetMin = goal.targetRange?.min ?? 8;
  const targetMax = goal.targetRange?.max ?? 9;
  const belowTargetRange = latestDEXA.bodyFatPercentage < targetMin;
  const bodyCompositionEstimate = getBodyCompositionEstimate(latestDEXA, evidence);
  const currentBodyFatEstimate = bodyCompositionEstimate?.pointEstimateBodyFatPercent ?? null;
  const progressValue = currentBodyFatEstimate ?? latestDEXA.bodyFatPercentage;
  const bodyFatTrend = getBodyFatTrend(evidence.dexaScans);
  const postDexaLoss = getWeightLossAfterDate(
    evidence.weightEntries,
    latestDEXA.measuredAt
  );
  const trendImproved = progressValue < latestDEXA.bodyFatPercentage;
  const projection = getProjection({
    goal,
    dexaScans: evidence.dexaScans,
    latestDEXA,
    weightEntries: evidence.weightEntries,
    bodyCompositionEstimate,
    progressPhotos: evidence.progressPhotos,
    now: evidence.now,
  });
  const protocolContextExists = evidence.protocols.some((protocol) =>
    protocol.relatedGoalIds?.includes(goal.id)
  );
  const evidenceIsConsistent =
    hasRecentWeightConsistency(evidence.weightEntries, evidence.now) &&
    evidence.dexaScans.length >= 3;
  const findings = [
    createFinding({
      id: "latest_dexa_verified",
      status: "positive",
      text: "Latest DEXA verifies body fat at 10.7%.",
      evidenceTypes: ["dexa"],
    }),
    createFinding({
      id: "post_dexa_trend",
      status: trendImproved ? "positive" : "neutral",
      text: trendImproved
        ? "Post-DEXA weight trend suggests movement toward the target range."
        : "Post-DEXA movement is not yet enough to update the estimate.",
      evidenceTypes: ["weight"],
    }),
    createFinding({
      id: "dexa_history_supports_direction",
      status: bodyFatTrend > 0 ? "positive" : "neutral",
      text:
        bodyFatTrend > 0
          ? "DEXA history supports the longer-term direction."
          : "DEXA history needs more improvement before confirming direction.",
      evidenceTypes: ["dexa"],
    }),
    createFinding({
      id: "evidence_consistency",
      status: evidenceIsConsistent ? "positive" : "neutral",
      text: evidenceIsConsistent
        ? "Recent evidence is consistent enough to trust the trend."
        : "More recent evidence would improve confidence in the trend.",
      evidenceTypes: ["weight", "dexa"],
    }),
    createFinding({
      id: "protocol_context",
      status: protocolContextExists ? "positive" : "neutral",
      text: protocolContextExists
        ? "Active protocol context supports interpretation of the current phase."
        : "Protocol context has not been linked to this goal.",
      evidenceTypes: ["protocol"],
    }),
    createFinding({
      id: "projection_available",
      status: projection ? "positive" : "neutral",
      text: projection
        ? "Projected trajectory points toward the target range."
        : "Projection remains pending until the trend is clearer.",
      evidenceTypes: ["dexa", "weight"],
    }),
    createFinding({
      id: "estimate_limited",
      status: "neutral",
      text: "Current body fat remains estimated until the next DEXA.",
      evidenceTypes: ["dexa", "weight"],
    }),
  ];
  const confidenceFactors = [
    createConfidenceFactor("latest_dexa", "Latest DEXA is a high-confidence calibration source.", 24),
    createConfidenceFactor("dexa_history", "Complete DEXA history supports trend context.", 10),
    createConfidenceFactor("manual_weights", "Manual morning weight trend supports direction.", 12),
    createConfidenceFactor("protocol_context", "Active protocol context explains the current phase.", 5),
    createConfidenceFactor("estimated_current_bf", "Current body fat is estimated after the scan.", -6),
  ];
  const progress = getMaintenanceProgress({
    dexaScans: evidence.dexaScans,
    progressValue,
    targetMax,
    bodyFatTrend,
    postDexaLoss,
    projection,
    protocolContextExists,
    evidenceIsConsistent,
    hasCurrentEstimate: currentBodyFatEstimate !== null,
  });
  const goalConfidence = getGoalConfidence({
    confidenceFactors,
    evidence,
    findings,
    missingEvidence: ["next_dexa_confirmation"],
  });
  const projectionWithConfidence = attachProjectionConfidence(projection, goalConfidence);

  return createEvaluation({
    goal,
    title: "Maintenance",
    current: `${latestDEXA.bodyFatPercentage.toFixed(1)}%`,
    target: `${targetMin}-${targetMax}%`,
    summary: belowTargetRange
      ? `Current DEXA is ${latestDEXA.bodyFatPercentage.toFixed(1)}%, below the ${targetMin}-${targetMax}% maintenance range. Establishing maintenance is the next decision.`
      : "Body-fat trend is moving toward the target range.",
    progress,
    confidence: goalConfidence,
    findings,
    recommendations: [
      createRecommendation("confirm_next_dexa", "Use the next DEXA to confirm the current estimate."),
    ],
    confidenceFactors,
    missingEvidence: ["next_dexa_confirmation"],
    projection: projectionWithConfidence,
    lifecycleState: belowTargetRange ? "transition_ready" : "active",
    thresholdStatus: belowTargetRange ? "exceeded" : "in_progress",
    terminalReason: belowTargetRange ? "The cut threshold has been reached and the current result is below the intended maintenance range." : null,
    requiredAction: belowTargetRange ? "Decide how to establish the maintenance phase." : null,
    transitionReady: belowTargetRange,
    metadata: {
      currentBodyFatEstimate,
      currentBodyFatEstimateRange: formatBodyCompositionRange(bodyCompositionEstimate),
      bodyCompositionEstimate,
      postDexaLoss,
      bodyFatTrend,
    },
    presentation: {
      mode: "supporting_objective",
      status: belowTargetRange ? "Ready for next phase" : projection ? "Entering Target Range" : "On Track",
      detail: belowTargetRange ? "Currently below target range" : "High Confidence",
      label: "Forecast",
    },
  });
}

function evaluateLeanMass(goal, evidence) {
  const latestDEXA = evidence.dexaScans.at(-1) ?? null;
  const leanMass = latestDEXA?.leanMass?.value ?? null;

  if (leanMass === null) {
    return createEvaluation({
      goal,
      title: "Lean Mass",
      current: "Pending",
      target: "Preserve",
      summary: missingDexaSummary(evidence, "calibrate lean-mass status"),
      progress: 0,
      confidence: 0,
      missingEvidence: ["dexa_scan"],
    });
  }

  const baseline = evidence.dexaScans.find((scan) => scan.measuredAt === "2026-05-24") ?? null;
  const referenceLeanMass = baseline?.leanMass?.value ?? 149.1;
  const preservedRatio = leanMass / referenceLeanMass;
  const achieved = preservedRatio >= LEAN_MASS_PRESERVATION_RATIO;
  const progress = clamp(Math.round(preservedRatio * 86), 0, 86);
  const findings = [
    createFinding({
      id: "latest_lean_mass_verified",
      status: "positive",
      text: `Latest DEXA verifies lean mass at ${leanMass.toFixed(1)} ${latestDEXA.leanMass.unit}.`,
      evidenceTypes: ["dexa"],
    }),
    createFinding({
      id: "next_scan_needed",
      status: "neutral",
      text: "Preservation remains provisional until the next DEXA.",
      evidenceTypes: ["dexa"],
    }),
  ];
  const confidenceFactors = [
    createConfidenceFactor("dexa_lean_mass", "DEXA is the authority for lean-mass status.", 22),
    createConfidenceFactor("between_scans", "Preservation is confidence-limited between scans.", -8),
  ];

  return createEvaluation({
    goal,
    title: "Lean Mass",
    current: `${leanMass.toFixed(1)} ${latestDEXA.leanMass.unit}`,
    target: "Preserve",
    summary: achieved
      ? `Lean tissue was preserved at ${leanMass.toFixed(1)} ${latestDEXA.leanMass.unit}, ${formatSigned(leanMass - referenceLeanMass)} ${latestDEXA.leanMass.unit} from the May 24 baseline.`
      : "Lean-mass preservation needs review.",
    progress: achieved ? null : progress,
    confidence: getGoalConfidence({
      confidenceFactors,
      evidence,
      findings,
      missingEvidence: ["next_dexa_confirmation"],
    }),
    findings,
    recommendations: [
      createRecommendation("preserve_protein", "Keep protein and training consistency high."),
    ],
    confidenceFactors,
    missingEvidence: achieved ? [] : ["next_dexa_confirmation"],
    lifecycleState: achieved ? "achieved" : "active",
    thresholdStatus: achieved ? "complete" : "in_progress",
    terminalReason: achieved ? "Jul 18 DEXA confirms lean-tissue preservation through the cut." : null,
    requiredAction: achieved ? "Review the next-goal decision." : null,
    transitionReady: achieved,
    achievementEvidence: achieved ? {
      baselineDate: baseline?.measuredAt ?? "2026-05-24",
      baselineLeanMass: referenceLeanMass,
      currentDate: latestDEXA.measuredAt,
      currentLeanMass: leanMass,
      delta: Number((leanMass - referenceLeanMass).toFixed(1)),
      unit: latestDEXA.leanMass.unit,
      preservationRatio: Number(preservedRatio.toFixed(4)),
      preservationToleranceRatio: LEAN_MASS_PRESERVATION_RATIO,
      decisionBasis: "latest_lean_mass_at_or_above_preservation_tolerance",
    } : null,
    presentation: {
      mode: "supporting_objective",
      status: achieved ? "Achieved" : "Under review",
      detail: achieved ? `${leanMass.toFixed(1)} lb latest · ${formatPresentationDelta(leanMass - referenceLeanMass)} lb` : "Last DEXA",
      label: "Trend",
    },
  });
}

function formatPresentationDelta(value) {
  return `${value > 0 ? "+" : value < 0 ? "−" : ""}${Math.abs(value).toFixed(1)}`;
}

function missingDexaSummary(evidence, purpose) {
  return evidence.invalidDexaCount > 0
    ? `The latest DEXA is incomplete and cannot ${purpose}. Review or reprocess that scan.`
    : `Add DEXA evidence to ${purpose}.`;
}

function createEvaluation({
  goal,
  title = goal.title,
  current,
  target,
  summary,
  progress,
  confidence,
  findings = [],
  recommendations = [],
  confidenceFactors = [],
  missingEvidence = [],
  projection = null,
  metadata = {},
  presentation = null,
  lifecycleState = "active",
  thresholdStatus = "in_progress",
  confirmationType = null,
  confirmationStatus = null,
  terminalReason = null,
  requiredAction = null,
  actionLabel = null,
  actionHref = null,
  achievementEvidence = null,
  transitionReady = false,
}) {
  return {
    id: `goal_evaluation_${goal.id}`,
    goalId: goal.id,
    metricKey: goal.metricKey,
    title,
    primary: Boolean(goal.primary),
    current,
    target,
    summary,
    progress,
    confidence: getConfidenceValue(confidence),
    goalProgress: progress == null ? null : { value: progress, label: `${progress}% complete` },
    goalConfidence: normalizeConfidence(confidence),
    findings,
    recommendations,
    confidenceFactors,
    missingEvidence,
    projection,
    metadata,
    presentation,
    lifecycleState,
    thresholdStatus,
    confirmationType,
    confirmationStatus,
    terminalReason,
    requiredAction,
    actionLabel,
    actionHref,
    achievementEvidence,
    transitionReady,
  };
}

function createFinding({ id, status, text, evidenceTypes }) {
  return {
    id,
    status,
    text,
    evidenceTypes,
  };
}

function createRecommendation(id, text) {
  return {
    id,
    text,
  };
}

function createConfidenceFactor(id, text, impact) {
  return {
    id,
    text,
    impact,
  };
}

function getBodyCompositionEstimate(latestDEXA, evidence) {
  return createBodyCompositionEstimate({
    latestDEXA,
    weightEntries: evidence.weightEntries,
    progressPhotos: evidence.progressPhotos,
    photoAnalyses: evidence.photoAnalyses,
    trainingPerformance: evidence.trainingPerformance,
    now: evidence.now,
  });
}

function getProjection({ goal, dexaScans = [], latestDEXA, weightEntries, bodyCompositionEstimate = null, progressPhotos = [], now }) {
  if (!latestDEXA?.totalMass?.value || !latestDEXA?.fatMass?.value) {
    return null;
  }

  const postDexaWeights = weightEntries.filter(
    (entry) => entry.measuredAt >= latestDEXA.measuredAt
  );

  if (postDexaWeights.length < 2) {
    return getDexaTrendProjection({ goal, dexaScans, latestDEXA, now });
  }

  const latestWeight = postDexaWeights.at(-1);
  const rollingTrend = getRollingWeightTrend(postDexaWeights);
  const lossRatePerDay =
    rollingTrend?.lossRatePerDay ??
    getRecentPositiveLossRate(postDexaWeights) ??
    getRecentPositiveLossRate(weightEntries);
  const estimatedBodyFat = bodyCompositionEstimate?.pointEstimateBodyFatPercent ?? estimateCurrentBodyFatFromWeight(latestDEXA, weightEntries);

  if (!lossRatePerDay || lossRatePerDay <= 0) {
    return getDexaTrendProjection({ goal, dexaScans, latestDEXA, now });
  }

  const projectionAnchorDate = rollingTrend?.anchorDate ?? latestWeight.measuredAt;

  const estimatedFatMass =
    estimatedBodyFat !== null
      ? latestWeight.weight.value * (estimatedBodyFat / 100)
      : latestDEXA.fatMass.value;
  const estimatedNonFatMass = latestWeight.weight.value - estimatedFatMass;
  const targetHighWeight = estimatedNonFatMass / 0.91;
  const trendWeight = rollingTrend?.trendWeight ?? latestWeight.weight.value;
  const remaining = Math.max(0, trendWeight - targetHighWeight);
  const estimatedDays =
    estimatedBodyFat !== null && estimatedBodyFat <= 9.9
      ? Math.min(20, Math.max(7, remaining / lossRatePerDay))
      : remaining / lossRatePerDay;

  if (!Number.isFinite(estimatedDays) || estimatedDays > 90) return null;

  const projectionWindow = getStabilizedProjectionWindow({
    anchorDate: projectionAnchorDate,
    estimatedDays,
  });
  const timelineSemantics = getTimelineSemantics({
    bodyCompositionEstimate,
    goal,
    now,
    progressPhotos,
  });

  return createGoalProjection({
    goal,
    now,
    evidenceThroughDate: latestWeight.measuredAt,
    projectionAnchorDate,
    projectionWindow,
    estimatedDays,
    expectedProgressRate: lossRatePerDay,
    estimatedRemainingChange: remaining,
    currentBodyFatEstimate: estimatedBodyFat,
    currentBodyFatRange: bodyCompositionEstimate
      ? formatBodyCompositionRange(bodyCompositionEstimate)
      : formatBodyFatEstimateRange(estimatedBodyFat, { latestDEXA, weightEntries: postDexaWeights }),
    bodyCompositionEstimate,
    timelineSemantics,
  });
}

function getDexaTrendProjection({ goal, dexaScans, latestDEXA, now }) {
  const previousDEXA = dexaScans.at(-2) ?? null;

  if (!previousDEXA?.bodyFatPercentage || !latestDEXA?.bodyFatPercentage) {
    return null;
  }

  const elapsedDays = Math.max(
    1,
    daysBetween(previousDEXA.measuredAt, latestDEXA.measuredAt)
  );
  const bodyFatLossRate =
    (previousDEXA.bodyFatPercentage - latestDEXA.bodyFatPercentage) / elapsedDays;
  const remainingBodyFat = latestDEXA.bodyFatPercentage - 9;

  if (bodyFatLossRate <= 0 || remainingBodyFat <= 0) return null;

  const estimatedDays = remainingBodyFat / bodyFatLossRate;

  if (!Number.isFinite(estimatedDays) || estimatedDays > 45) return null;

  const asOfDate = getLocalDateKey(now);
  const earliestDate = toDateKey(addDays(asOfDate, Math.max(0, Math.floor(estimatedDays * 0.8))));
  const latestDate = toDateKey(addDays(asOfDate, Math.ceil(estimatedDays * 1.2) + 2));
  const expectedDate = toDateKey(addDays(asOfDate, Math.round(estimatedDays)));

  return createGoalProjection({
    goal,
    now,
    evidenceThroughDate: latestDEXA.measuredAt,
    projectionAnchorDate: latestDEXA.measuredAt,
    projectionWindow: {
      earliestDate,
      expectedDate,
      latestDate,
      label: formatDateRange(parseDate(earliestDate), parseDate(latestDate)),
    },
    estimatedDays,
    expectedProgressRate: bodyFatLossRate,
    estimatedRemainingChange: remainingBodyFat,
    currentBodyFatEstimate: latestDEXA.bodyFatPercentage,
    currentBodyFatRange: null,
  });
}

function getRollingWeightTrend(weightEntries) {
  const sortedWeights = sortByDate(weightEntries, "measuredAt");

  if (sortedWeights.length < ROLLING_TREND_WINDOW_DAYS + 1) return null;

  const rollingPoints = [];

  for (
    let index = ROLLING_TREND_WINDOW_DAYS - 1;
    index < sortedWeights.length;
    index += 1
  ) {
    const window = sortedWeights.slice(index - ROLLING_TREND_WINDOW_DAYS + 1, index + 1);
    const windowDays = daysBetween(window[0].measuredAt, window.at(-1).measuredAt);

    if (window.length < ROLLING_TREND_WINDOW_DAYS || windowDays < ROLLING_TREND_WINDOW_DAYS - 1) {
      continue;
    }

    rollingPoints.push({
      date: window.at(-1).measuredAt,
      value:
        window.reduce((total, entry) => total + entry.weight.value, 0) /
        window.length,
    });
  }

  if (rollingPoints.length < 2) return null;

  const first = rollingPoints[0];
  const latest = rollingPoints.at(-1);
  const elapsedDays = Math.max(1, daysBetween(first.date, latest.date));
  const lossRatePerDay = (first.value - latest.value) / elapsedDays;

  if (!Number.isFinite(lossRatePerDay) || lossRatePerDay <= 0) return null;

  return {
    anchorDate: latest.date,
    lossRatePerDay,
    trendWeight: latest.value,
  };
}

function getStabilizedProjectionWindow({ anchorDate, estimatedDays }) {
  const projectedCenter = addDays(anchorDate, Math.max(0, Math.round(estimatedDays)));
  const stableCenter = snapDateToDayBucket(projectedCenter, PROJECTION_BUCKET_DAYS);
  const earliestDate = toDateKey(addDays(stableCenter, -PROJECTION_WINDOW_RADIUS_DAYS));
  const expectedDate = toDateKey(stableCenter);
  const latestDate = toDateKey(addDays(stableCenter, PROJECTION_WINDOW_RADIUS_DAYS));

  return {
    earliestDate,
    expectedDate,
    latestDate,
    label: formatDateRange(parseDate(earliestDate), parseDate(latestDate)),
  };
}

function createGoalProjection({
  goal,
  now,
  evidenceThroughDate,
  projectionAnchorDate,
  projectionWindow,
  estimatedDays,
  expectedProgressRate,
  estimatedRemainingChange,
  currentBodyFatEstimate,
  currentBodyFatRange,
  bodyCompositionEstimate = null,
  timelineSemantics = null,
}) {
  const asOfDate = getLocalDateKey(now);
  const minimumDaysRemaining = Math.max(0, daysBetween(asOfDate, projectionWindow.earliestDate));
  const expectedDaysRemaining = Math.max(0, daysBetween(asOfDate, projectionWindow.expectedDate));
  const maximumDaysRemaining = Math.max(0, daysBetween(asOfDate, projectionWindow.latestDate));

  return {
    id: `goal_projection_${goal?.id ?? "unknown"}_${asOfDate}_${evidenceThroughDate}`,
    asOfDate,
    evidenceThroughDate,
    goal: {
      id: goal?.id ?? null,
      title: goal?.title ?? null,
    },
    currentEstimate: {
      value: currentBodyFatEstimate,
      range: currentBodyFatRange,
      unit: "%",
      method: bodyCompositionEstimate?.method ?? "DEXA-calibrated weight trend",
      estimateId: bodyCompositionEstimate?.id ?? null,
    },
    target: goal?.targetRange ?? goal?.targetValue ?? "Visible at rest",
    confidence: null,
    confidenceMeaning:
      "Confidence in the overall goal trajectory assessment, not certainty in the numerical body-fat estimate.",
    earliestCompletionDate: projectionWindow.earliestDate,
    expectedCompletionDate: projectionWindow.expectedDate,
    latestCompletionDate: projectionWindow.latestDate,
    minimumDaysRemaining,
    expectedDaysRemaining,
    maximumDaysRemaining,
    status: "on_track",
    currentCompletionStage: timelineSemantics?.currentCompletionStage ?? "progressing_toward_numerical_target",
    completionStageLabel: timelineSemantics?.completionStageLabel ?? "Progressing toward numerical target",
    remainingCriterion: timelineSemantics?.remainingCriterion ?? "Reach the numerical body-composition target.",
    nextEvidenceCheckpoint: timelineSemantics?.nextEvidenceCheckpoint ?? null,
    assumedCheckpointCount: timelineSemantics?.assumedCheckpointCount ?? 0,
    projectionBasis: timelineSemantics?.projectionBasis ?? "DEXA-calibrated body-composition progress",
    uncertaintyReason: timelineSemantics?.uncertaintyReason ?? "The rate of body-composition change may vary.",
    supportingExplanation: timelineSemantics?.supportingExplanation ?? "Body-composition progress still determines the timeline.",
    numericalThresholdStatus: timelineSemantics?.numericalThresholdStatus ?? "not_reached",
    visualConfirmationStatus: timelineSemantics?.visualConfirmationStatus ?? "not_applicable",
    assumptions: {
      projectionAnchorDate,
      rawEstimatedDays: Number(estimatedDays.toFixed(2)),
      expectedProgressRate: Number(expectedProgressRate.toFixed(4)),
      estimatedRemainingChange: Number(estimatedRemainingChange.toFixed(2)),
      stabilityBucketDays: PROJECTION_BUCKET_DAYS,
      windowRadiusDays: PROJECTION_WINDOW_RADIUS_DAYS,
    },
    currentBodyFatEstimate,
    currentBodyFatRange,
    bodyCompositionEstimate,
    projectedFinish: projectionWindow.label,
    daysRemaining: formatProjectionDuration({
      minimumDaysRemaining,
      expectedDaysRemaining,
      maximumDaysRemaining,
    }),
  };
}

export function getTimelineSemantics({ bodyCompositionEstimate, goal, now = new Date(), progressPhotos = [], visualConfirmed = false, visualProgressSupported = true } = {}) {
  const isVisualGoal = goal?.id === VISIBLE_ABS_GOAL_ID || goal?.metricKey === "visualDefinition";
  const targetUpper = goal?.supportingBodyFatRange?.max ?? goal?.targetRange?.max ?? 9;
  const estimateInRange = Boolean(bodyCompositionEstimate && bodyCompositionEstimate.pointEstimateBodyFatPercent <= targetUpper && bodyCompositionEstimate.lowerBodyFatPercent <= targetUpper);
  if (!isVisualGoal || !estimateInRange) {
    return {
      currentCompletionStage: "progressing_toward_numerical_target",
      completionStageLabel: "Progressing toward numerical target",
      remainingCriterion: "Reach the numerical body-composition target before visual confirmation becomes decisive.",
      nextEvidenceCheckpoint: null,
      assumedCheckpointCount: 0,
      projectionBasis: "DEXA-calibrated body-composition progress",
      uncertaintyReason: "The numerical threshold has not yet been reached.",
      supportingExplanation: "Body-composition progress still determines the timeline.",
      numericalThresholdStatus: "not_reached",
      visualConfirmationStatus: "not_applicable",
    };
  }

  const nextEvidenceCheckpoint = getNextWeeklyPhotoCheckpoint({ now, progressPhotos });
  if (visualConfirmed) {
    return {
      currentCompletionStage: "goal_visually_confirmed", completionStageLabel: "Goal visually confirmed",
      remainingCriterion: null, nextEvidenceCheckpoint, assumedCheckpointCount: 0,
      projectionBasis: "Comparable progress photos confirm the visual goal.", uncertaintyReason: null,
      supportingExplanation: "Comparable progress photos now confirm visible abs at rest.",
      numericalThresholdStatus: "reached", visualConfirmationStatus: "confirmed",
    };
  }

  return {
    currentCompletionStage: visualProgressSupported ? "visual_confirmation_developing" : "awaiting_visual_confirmation",
    completionStageLabel: visualProgressSupported ? "Visual confirmation developing" : "Awaiting visual confirmation",
    remainingCriterion: "Consistent visible lower-ab definition at rest in comparable progress photos.",
    nextEvidenceCheckpoint,
    assumedCheckpointCount: 2,
    projectionBasis: "Upcoming weekly comparable progress-photo check-ins",
    uncertaintyReason: visualProgressSupported
      ? "The first check-in may confirm the goal, while a second may be needed to establish consistency."
      : "Comparable photo evidence is still needed; a missed check-in does not imply physiological regression.",
    supportingExplanation: "Your estimated body composition is already in the target range. Comparable progress photos are now the deciding evidence, and the next one or two check-ins should clarify completion.",
    numericalThresholdStatus: "reached",
    visualConfirmationStatus: visualProgressSupported ? "developing" : "awaiting_comparable_evidence",
  };
}

function getNextWeeklyPhotoCheckpoint({ now, progressPhotos }) {
  const asOfDate = getLocalDateKey(now);
  const latestDate = [...new Set(progressPhotos.map((photo) => String(photo.date ?? photo.capturedAt ?? "").slice(0, 10)).filter(Boolean))].sort().at(-1);
  let checkpoint = latestDate ? addDays(latestDate, 7) : addDays(asOfDate, 7);
  while (toDateKey(checkpoint) < asOfDate) checkpoint = addDays(checkpoint, 7);
  return toDateKey(checkpoint);
}

function attachProjectionConfidence(projection, goalConfidence) {
  if (!projection) return null;

  return {
    ...projection,
    confidence: {
      value: goalConfidence?.value ?? 0,
      label: goalConfidence?.label ?? "Building",
      meaning: projection.confidenceMeaning,
    },
  };
}

function snapDateToDayBucket(value, bucketDays) {
  const date = value instanceof Date ? new Date(value) : parseDate(value);
  const epochDay = Math.round(date.getTime() / DAY_MS);
  const snappedDay = Math.round(epochDay / bucketDays) * bucketDays;

  return new Date(snappedDay * DAY_MS + DAY_MS / 2);
}

function getRecentPositiveLossRate(weightEntries) {
  const sortedWeights = sortByDate(weightEntries, "measuredAt");

  for (let endIndex = sortedWeights.length - 1; endIndex > 0; endIndex -= 1) {
    for (let startIndex = 0; startIndex < endIndex; startIndex += 1) {
      const start = sortedWeights[startIndex];
      const end = sortedWeights[endIndex];
      const elapsedDays = daysBetween(start.measuredAt, end.measuredAt);
      const loss = start.weight.value - end.weight.value;

      if (elapsedDays >= 3 && loss > 0) {
        return loss / elapsedDays;
      }
    }
  }

  return null;
}

function getBodyFatTrend(dexaScans) {
  if (dexaScans.length < 2) return 0;

  const earliest = dexaScans[0].bodyFatPercentage;
  const latest = dexaScans.at(-1).bodyFatPercentage;

  if (earliest === null || latest === null) return 0;

  return Math.max(0, earliest - latest);
}

function estimateCurrentBodyFatFromWeight(latestDEXA, weightEntries) {
  const latestWeight = weightEntries.at(-1);

  if (
    !latestWeight?.weight?.value ||
    !latestDEXA?.totalMass?.value ||
    !latestDEXA?.fatMass?.value ||
    latestWeight.measuredAt < latestDEXA.measuredAt
  ) {
    return null;
  }

  const postDexaLoss = Math.max(
    0,
    latestDEXA.totalMass.value - latestWeight.weight.value
  );
  const rollingTrend = getRollingWeightTrend(
    weightEntries.filter((entry) => entry.measuredAt >= latestDEXA.measuredAt)
  );
  const fatLossRatio = rollingTrend?.lossRatePerDay && rollingTrend.lossRatePerDay > 0
    ? 0.72
    : 0.62;
  const estimatedFatMass = Math.max(
    latestDEXA.fatMass.value * 0.72,
    latestDEXA.fatMass.value - postDexaLoss * fatLossRatio
  );

  return (estimatedFatMass / latestWeight.weight.value) * 100;
}

function formatBodyFatEstimateRange(value, { latestDEXA, weightEntries = [] } = {}) {
  if (typeof value !== "number" || Number.isNaN(value)) return null;

  const latestWeight = weightEntries.at(-1);
  const daysSinceDexa =
    latestDEXA?.measuredAt && latestWeight?.measuredAt
      ? Math.max(0, daysBetween(latestDEXA.measuredAt, latestWeight.measuredAt))
      : 0;
  const scaleOnlyInference = weightEntries.length > 1 && daysSinceDexa >= 7;
  const lowerSpread = scaleOnlyInference ? 0.45 : 0.2;
  const upperSpread = scaleOnlyInference ? 0.75 : 0.3;
  const lower = Math.max(0, value - lowerSpread);
  const upper = value + upperSpread;

  return `~${lower.toFixed(1)}-${upper.toFixed(1)}%`;
}

function getLeanMassPreservationScore(latestDEXA) {
  const leanMass = latestDEXA?.leanMass?.value ?? null;

  if (leanMass === null) return 0;

  return clamp(Math.round((leanMass / 149.1) * 100), 0, 100);
}

function getWeightLossAfterDate(weightEntries, date) {
  const entries = weightEntries.filter((entry) => entry.measuredAt >= date);

  if (entries.length < 2) return 0;

  return Number((entries[0].weight.value - entries.at(-1).weight.value).toFixed(1));
}

function getMaintenanceProgress({
  dexaScans,
  progressValue,
  targetMax,
  bodyFatTrend,
  postDexaLoss,
  projection,
  protocolContextExists,
  evidenceIsConsistent,
  hasCurrentEstimate,
}) {
  const latestVerified = dexaScans.at(-1)?.bodyFatPercentage ?? progressValue;
  const distanceScore = clamp(
    Math.round(((13.6 - progressValue) / (13.6 - targetMax)) * 42),
    0,
    42
  );
  const historyScore = clamp(dexaScans.length * 2 + Math.round(bodyFatTrend), 0, 20);
  const postDexaScore = clamp(Math.round(postDexaLoss * 3), 0, 10);
  const contextScore = (protocolContextExists ? 8 : 0) + (evidenceIsConsistent ? 10 : 0);
  const projectionScore = projection ? 8 : 0;
  const calibrationScore = hasCurrentEstimate && progressValue < latestVerified ? 6 : 0;

  return clamp(
    distanceScore +
      historyScore +
      postDexaScore +
      contextScore +
      projectionScore +
      calibrationScore,
    0,
    hasCurrentEstimate ? 92 : 86
  );
}

function hasRecentWeightConsistency(weightEntries, now) {
  const dates = new Set(weightEntries.map((entry) => entry.measuredAt?.slice(0, 10)));
  const today = now instanceof Date ? new Date(now) : new Date(now);
  let matches = 0;

  for (let offset = 0; offset < 7; offset += 1) {
    const cursor = new Date(today);
    cursor.setDate(today.getDate() - offset);
    if (dates.has(cursor.toISOString().slice(0, 10))) matches += 1;
  }

  return matches >= 5;
}

function hasConsistentProgressPhotos(progressPhotos) {
  if (progressPhotos.length < 3) return false;

  return progressPhotos.every(
    (photo) =>
      photo.conditions?.morning &&
      photo.conditions?.fasted &&
      photo.conditions?.sameLighting &&
      photo.conditions?.sameMirror &&
      photo.conditions?.postWorkout === false &&
      photo.conditions?.pump === false
  );
}

function formatGoalTarget(goal) {
  if (goal.targetRange) {
    return `${goal.targetRange.min}-${goal.targetRange.max}${goal.unit ?? ""}`;
  }

  return "Pending";
}

function sortByDate(records, field) {
  return [...records].sort((a, b) => String(a[field]).localeCompare(String(b[field])));
}

function daysBetween(value, otherValue) {
  const start = parseDate(value);
  const end = otherValue instanceof Date ? otherValue : parseDate(otherValue);

  return Math.floor((end.getTime() - start.getTime()) / DAY_MS);
}

function addDays(value, days) {
  const date = value instanceof Date ? new Date(value) : parseDate(value);
  date.setDate(date.getDate() + days);

  return date;
}

function parseDate(value) {
  return new Date(`${String(value).slice(0, 10)}T12:00:00`);
}

function formatDateRange(start, end) {
  const sameMonth =
    start.getFullYear() === end.getFullYear() && start.getMonth() === end.getMonth();
  const startText = formatShortDate(start);
  const endText = sameMonth ? String(end.getDate()) : formatShortDate(end);

  return startText === endText ? startText : `${startText}-${endText}`;
}

function formatShortDate(date) {
  return new Intl.DateTimeFormat("en-US", {
    month: "short",
    day: "numeric",
  }).format(date);
}

export function formatProjectionDuration({
  minimumDaysRemaining,
  expectedDaysRemaining,
  maximumDaysRemaining,
}) {
  if (maximumDaysRemaining <= 0) return "Today";
  if (minimumDaysRemaining === 1 && maximumDaysRemaining === 1) return "Tomorrow";
  if (maximumDaysRemaining <= 6) {
    return minimumDaysRemaining === maximumDaysRemaining
      ? `About ${expectedDaysRemaining} days`
      : `${minimumDaysRemaining}-${maximumDaysRemaining} days`;
  }
  if (maximumDaysRemaining === 7) return "0-1 week";
  if (minimumDaysRemaining >= 7 && maximumDaysRemaining <= 10) return "About 1 week";
  if (minimumDaysRemaining >= 8 && maximumDaysRemaining <= 14) return "1-2 weeks";
  if (minimumDaysRemaining >= 11 && maximumDaysRemaining <= 17) return "About 2 weeks";
  const low = Math.max(1, Math.floor(minimumDaysRemaining / 7));
  const high = Math.max(low + 1, Math.ceil(maximumDaysRemaining / 7));
  return `${low}-${high} weeks`;
}

function toDateKey(value) {
  const date = value instanceof Date ? value : parseDate(value);
  return [
    date.getFullYear(),
    String(date.getMonth() + 1).padStart(2, "0"),
    String(date.getDate()).padStart(2, "0"),
  ].join("-");
}

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function formatSigned(value) {
  return `${value > 0 ? "+" : ""}${value.toFixed(1)}`;
}

function getGoalConfidence({ confidenceFactors, evidence, findings, missingEvidence }) {
  return GoalConfidenceService.calculateGoalConfidence({
    confidenceFactors,
    evidence: {
      dexaScanCount: evidence.dexaScans.length,
      weightEntryCount: evidence.weightEntries.length,
      progressPhotoCount: evidence.progressPhotos.length,
      protocolCount: evidence.protocols.length,
    },
    findings,
    missingEvidence,
  });
}

function normalizeConfidence(confidence) {
  if (typeof confidence === "number") {
    return {
      value: confidence,
      label: getConfidenceLabel(confidence),
      factors: [],
      evidenceImpact: 0,
      agreementImpact: 0,
      missingEvidence: [],
    };
  }

  return confidence;
}

function getConfidenceValue(confidence) {
  return normalizeConfidence(confidence)?.value ?? 0;
}

function getConfidenceLabel(confidence) {
  if (confidence >= 90) return "Very High";
  if (confidence >= 80) return "High";
  if (confidence >= 55) return "Moderate";

  return "Building";
}
